INSERT INTO "PreGeneratedQuestion" (id, "questionType", system, difficulty, "questionData", "questionOrder", "taskCategory", "validationStatus", "generatedAt")
VALUES
('q-tax-cv-001', 'clinical-vignette', 'CV', 'easy', '{"question":"A 72-year-old man with a history of hypertension and diabetes presents with acute onset of retrosternal chest pain radiating to the left arm and jaw. EKG shows ST elevation in leads II, III, and aVF. Vital signs: BP 145/92, HR 105, RR 18, O2 sat 97% on room air.","options":["A. Immediate cardiac catheterization for primary PCI","B. Administer aspirin and clopidogrel, then arrange for stress testing in 48 hours","C. Administer nitrates and arrange for CABG consultation","D. Perform chest X-ray to evaluate for pulmonary edema"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"This patient presents with STEMI (inferior wall MI based on ST elevation in II, III, aVF). The standard of care for STEMI is immediate reperfusion therapy with primary percutaneous coronary intervention (PCI/cardiac catheterization) within 90 minutes of first medical contact. Time is myocardium—door-to-balloon time is critical. Option B is incorrect because stress testing delays necessary reperfusion and is contraindicated in acute MI. Option C (CABG) is a surgical option but PCI is preferred as immediate therapy. Option D does not address the acute coronary pathology.","conditionName":"STEMI - Inferior Wall","system":"CV","subcategory":"Acute Coronary Syndrome","tags":["CV","STEMI","ACS","acute-MI","reperfusion"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),
('q-tax-cv-002', 'clinical-vignette', 'CV', 'easy', '{"question":"A 55-year-old woman with hyperlipidemia presents with sudden onset of severe substernal chest pain and diaphoresis lasting 30 minutes. EKG shows ST depression in precordial leads with T-wave inversion. Troponin is elevated at 2.8 ng/mL (normal <0.04).","options":["A. Non-ST elevation myocardial infarction (NSTEMI)","B. Unstable angina","C. Stable angina with demand ischemia","D. Aortic dissection"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"This is a classic presentation of NSTEMI: elevated troponin indicating myocardial necrosis + ECG changes (ST depression, T-wave inversion) + symptoms. The lack of ST elevation distinguishes it from STEMI. Option B (unstable angina) presents with similar symptoms but does NOT have elevated troponin. Option C (stable angina) refers to predictable, exertional chest pain, not acute severe pain. Option D (aortic dissection) is a consideration with sudden severe chest pain, but the troponin elevation and specific ECG pattern point to ACS.","conditionName":"NSTEMI","system":"CV","subcategory":"Acute Coronary Syndrome","tags":["CV","NSTEMI","ACS","troponin","non-STEMI"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),
('q-tax-cv-003', 'clinical-vignette', 'CV', 'easy', '{"question":"A 68-year-old male with diabetes, hypertension, and smoking history develops acute decompensated heart failure with dyspnea, orthopnea, and bilateral lower extremity edema. Chest X-ray shows pulmonary edema. BNP is 650 pg/mL (normal <100).","options":["A. Diuretics and afterload reduction are the cornerstones of acute HF management","B. Inotropic support should be the first-line therapy","C. Sodium restriction alone is usually sufficient","D. ACE inhibitors should be withheld until volume is corrected"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Acute decompensated heart failure is managed with diuretics (to reduce pulmonary congestion) and afterload-reducing agents (nitrates, ACE inhibitors) to improve cardiac output. This is standard acute HF management. Option B: inotropes are reserved for cardiogenic shock or severe cases with hypotension. Option C: sodium restriction is part of chronic management but acute cases need diuretics. Option D: ACE inhibitors can be safely given in acute HF alongside diuretics and are beneficial for long-term outcomes.","conditionName":"Acute Decompensated Heart Failure","system":"CV","subcategory":"Heart Failure","tags":["CV","acute-HF","decompensation","pulmonary-edema"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'basic_science', 'pending', NOW()),
('q-tax-cv-004', 'clinical-vignette', 'CV', 'easy', '{"question":"A 70-year-old woman with chronic systolic heart failure (EF 25%) on optimal medical therapy presents with progressive dyspnea despite compliance with furosemide and enalapril. She has a BP of 98/62 and HR of 102. The most appropriate next step in her management is:","options":["A. Increase the dose of furosemide to 240 mg daily","B. Add aldosterone antagonist and consider device therapy (ICD/CRT)","C. Initiate inotropic therapy with dobutamine infusion","D. Recommend lung transplantation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has advanced (Stage C) systolic heart failure refractory to standard therapy. The next appropriate steps are: (1) addition of an aldosterone antagonist (spironolactone) which improves mortality in systolic HF, and (2) evaluation for device therapy (implantable cardioverter-defibrillator for EF <35%, or cardiac resynchronization therapy if QRS >120ms). Option A: increasing diuretics may worsen renal function given low BP. Option C: chronic inotropes worsen outcomes in systolic HF. Option D: transplant is considered only after maximal medical and device therapy.","conditionName":"Chronic Systolic Heart Failure","system":"CV","subcategory":"Heart Failure","tags":["CV","chronic-HF","reduced-EF","device-therapy"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),
('q-tax-cv-005', 'clinical-vignette', 'CV', 'medium', '{"question":"A 62-year-old man with a history of myocardial infarction develops new onset irregular pulse with a heart rate varying between 60 and 110 bpm. His symptoms include mild dyspnea and palpitations. EKG confirms absence of P waves with an irregularly irregular ventricular response.","options":["A. Atrial flutter","B. Atrial fibrillation","C. Sinus tachycardia with premature atrial contractions","D. Ventricular fibrillation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"The irregular pulse with varying rate and absent P waves on EKG is diagnostic of atrial fibrillation (AF). The rhythm is irregularly irregular (random intervals between beats). Option A (atrial flutter) has regular ventricular response unless variable AV block. Option C (sinus tach with PACs) would show identifiable P waves. Option D (VF) presents with hemodynamic instability and no organized rhythm. AF is common post-MI and increases stroke risk—anticoagulation assessment is critical.","conditionName":"Atrial Fibrillation","system":"CV","subcategory":"Arrhythmias","tags":["CV","AF","atrial-fibrillation","post-MI"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'basic_science', 'pending', NOW()),
('q-tax-cv-006', 'clinical-vignette', 'CV', 'easy', '{"question":"A 58-year-old male with uncontrolled hypertension (BP 185/110) presents with severe headache, blurred vision, and mild left-sided weakness. His serum creatinine is 2.1 mg/dL (baseline 0.9) and urinalysis shows protein. Brain CT is normal. What is the most likely diagnosis?","options":["A. Hemorrhagic stroke","B. Hypertensive urgency","C. Hypertensive emergency with end-organ damage","D. Acute disseminated encephalomyelitis"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This patient has hypertensive emergency: severe hypertension (>180/120) WITH end-organ damage evidenced by: neurologic symptoms (headache, vision changes, focal weakness suggesting hypertensive encephalopathy), acute kidney injury (elevated creatinine, proteinuria), and high BP. Hypertensive urgency is elevated BP without acute end-organ injury. Option A (hemorrhagic stroke) is possible but the normal brain CT makes hypertensive encephalopathy more likely. This requires IV antihypertensive therapy with careful titration (avoid rapid drops >25% in 24h).","conditionName":"Hypertensive Emergency","system":"CV","subcategory":"Hypertension","tags":["CV","hypertensive-emergency","end-organ-damage","hypertensive-encephalopathy"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'health_maintenance', 'pending', NOW()),
('q-tax-cv-007', 'clinical-vignette', 'CV', 'medium', '{"question":"A 45-year-old woman with systemic lupus erythematosus presents with acute onset pleuritic chest pain and pericardial friction rub on examination. EKG shows diffuse ST-segment elevation with PR depression. Which of the following is the most likely diagnosis?","options":["A. Acute myocardial infarction","B. Acute pericarditis","C. Pulmonary embolism","D. Pneumothorax"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is acute pericarditis: pleuritic chest pain (worse with breathing/lying supine), pericardial friction rub on auscultation, and characteristic EKG findings (diffuse ST elevation + PR depression, distinguishing it from MI which shows regional ST elevation). SLE is a risk factor for pericarditis. Option A (MI) would show localized ST elevation, typically no friction rub, and usually has risk factors. Option C (PE) causes pleuritic pain but no friction rub or this EKG pattern. Option D (pneumothorax) would show hyperlucency on chest X-ray, not these findings.","conditionName":"Acute Pericarditis","system":"CV","subcategory":"Pericardial Disease","tags":["CV","pericarditis","SLE","pleuritic-pain"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),
('q-tax-cv-008', 'clinical-vignette', 'CV', 'medium', '{"question":"A 72-year-old man with a history of aortic valve replacement 15 years ago presents with fever, night sweats, and a new systolic murmur. Blood cultures grow Streptococcus bovis. Echocardiography reveals a 1.2 cm vegetation on the prosthetic valve with paravalvular regurgitation. What is the best treatment?","options":["A. Antibiotics alone for 6 weeks","B. Antibiotics for 2 weeks followed by surgical valve replacement","C. Surgical valve replacement plus prolonged antibiotic therapy","D. Anticoagulation to prevent septic emboli"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This is prosthetic valve endocarditis (PVE), a surgical emergency. Indications for surgery in PVE include: heart failure, large vegetations (>10mm), paravalvular regurgitation, and prosthetic valve dysfunction. Option A (antibiotics alone) is inadequate—PVE with these features requires urgent surgical management. Option B (early surgery + short antibiotics) undershoots needed antibiotic duration. Option C is correct: early surgical valve replacement combined with prolonged antibiotics (at least 6 weeks for prosthetic valve endocarditis with culture-positive sepsis). Option D: anticoagulation is contraindicated in endocarditis due to embolic risk.","conditionName":"Prosthetic Valve Endocarditis","system":"CV","subcategory":"Endocarditis","tags":["CV","endocarditis","PVE","prosthetic-valve","streptococcus"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),
('q-tax-cv-009', 'clinical-vignette', 'CV', 'medium', '{"question":"A 55-year-old man with a history of cocaine use disorder presents with acute severe retrosternal chest pain radiating to the back. BP is 165/95 in the right arm and 140/88 in the left arm. Chest X-ray shows widened mediastinum. CT angiography of the chest shows a dissection beginning at the ascending aorta extending to the thoracic descending aorta with no branch involvement.","options":["A. Urgent surgical intervention (CABG)","B. Aggressive blood pressure and heart rate control followed by surgical repair","C. Conservative medical therapy with ACE inhibitors","D. Mechanical thrombectomy"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has acute aortic dissection (Type A—involving ascending aorta), a surgical emergency. The cocaine use is a known risk factor. The blood pressure differential between arms (25 mmHg systolic) and widened mediastinum support the diagnosis. Type A dissection requires: (1) aggressive BP/HR control (target SBP 100-120, HR 60, using beta-blocker first, then vasodilator), then (2) urgent surgical repair. Option A is incomplete (need medical management first). Option C (conservative therapy) is incorrect for Type A—mortality without surgery is ~1% per hour. Option D: thrombectomy has no role in dissection.","conditionName":"Acute Aortic Dissection - Type A","system":"CV","subcategory":"Aortic Dissection","tags":["CV","aortic-dissection","cocaine","Type-A","surgical-emergency"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),
('q-tax-cv-010', 'clinical-vignette', 'CV', 'medium', '{"question":"A 68-year-old woman with dyslipidemia and no known coronary disease has LDL 145 mg/dL and HDL 38 mg/dL. She has 10% 10-year cardiovascular risk by Framingham. She is currently on atorvastatin 20 mg daily. What is the most appropriate next step?","options":["A. Continue current statin dose; recheck lipids in 6 months","B. Uptitrate atorvastatin to 40-80 mg daily to achieve LDL <70 mg/dL","C. Add ezetimibe and consider PCSK9 inhibitor","D. Discontinue statin and trial lifestyle modification alone"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"According to ATP III and current guidelines, this patient needs LDL <100 mg/dL (goal <70 for very high risk or those with 10-year risk >20%). She is on a moderate-intensity statin (atorvastatin 20 mg) and is not at goal. The appropriate next step is to uptitrate to high-intensity statin therapy (atorvastatin 40-80 mg daily). Option A: insufficient dose for her risk. Option C: ezetimibe/PCSK9i are added after maximizing statin therapy. Option D: discontinuing statins is inappropriate given dyslipidemia and CAD risk.","conditionName":"Dyslipidemia","system":"CV","subcategory":"Risk Factors","tags":["CV","dyslipidemia","statin","lipid-management","LDL"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'pharmaceutical', 'pending', NOW());